static void knc_flush ( struct thr_info * thr ) { struct cgpu_info * cgpu = thr -> cgpu ; struct knc_state * knc = cgpu -> device_data ; struct knc_spi_buffer * buffer = & knc -> spi_buffer [ knc -> send_buffer ] ; if ( buffer -> state == KNC_SPI_IDLE && buffer -> size > 0 ) { pthread_mutex_lock ( & knc -> spi_qlock ) ; buffer -> state = KNC_SPI_PENDING ; pthread_cond_signal ( & knc -> spi_qcond ) ; knc -> send_buffer += 1 ; knc -> send_buffer_count += 1 ; buffer = & knc -> spi_buffer [ knc -> send_buffer ] ; while ( buffer -> state == KNC_SPI_PENDING ) { applog ( LOG_DEBUG , "KnC: SPI buffer full (%d), waiting for SPI thread" , buffer -> responses ) ; pthread_cond_wait ( & knc -> spi_qcond , & knc -> spi_qlock ) ; } pthread_mutex_unlock ( & knc -> spi_qlock ) ; } knc_process_responses ( thr ) ; } 